#include <vector>
#include <string>
#include <omp.h>
#include <cstddef>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    // If no qualifying book exists, return books.size() as a sentinel "not found" index.
    size_t lastIndex = books.size();

    #pragma omp parallel
    {
        size_t localLast = books.size();

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(books.size()); ++i) {
            if (books[static_cast<size_t>(i)].pages < 100) {
                localLast = static_cast<size_t>(i); // increasing i in each thread's chunk
            }
        }

        #pragma omp critical
        {
            if (localLast != books.size()) {
                if (lastIndex == books.size() || localLast > lastIndex) {
                    lastIndex = localLast;
                }
            }
        }
    }

    return lastIndex;
}
